class Solution {
public:
    int findNthDigit(int n) {
        long long N = n;
        long long len = 1;
        long long count = 9;
        long long start = 1;

        while (N > len * count) {
            N -= len * count;
            len++;
            count *= 10;
            start *= 10;
        }

        long long num = start + (N - 1) / len;
        long long d = (N - 1) % len;
        long long right = len - 1 - d;

        for (long long i = 0; i < right; i++) {
            num /= 10;
        }

        return num % 10;
    }
};
